body.script:
    // ==================== CHANGE THIS ONE URL ====================

    const REDIRECT_URL = "https://freshmorningstart.com/bvu1cjs8n?key=338a5b669fb3b4df1fb27898bd934655";

    // ==================== EDIT VIDEOS HERE ====================

    const videoData = [
      {
        src:      "https://xcdn.tv/cdn/storage/production/gifreels/post/NVkk0V/gif-240.mp4",
        username: "@nature_lens",
        caption:  "Golden hour timelapse 🌅",
        avatar:   "NL",
        likes:    "24.8K",
        views:    "104K"
      },
      {
        src:      "https://xcdn.tv/cdn/storage/production/gifreels/post/D5uLcM/gif-240.mp4",
        username: "@travel_diaries",
        caption:  "Hidden gems of Bali 🏝️",
        avatar:   "TD",
        likes:    "18.2K",
        views:    "87K"
      },
      {
        src:      "https://xcdn.tv/cdn/storage/production/gifreels/post/VIGav9/gif-240.mp4",
        username: "@sports_hub",
        caption:  "Epic dunk compilation 🏀",
        avatar:   "SH",
        likes:    "31.5K",
        views:    "215K"
      },
      {
        src:      "https://p5rn.com/cdn/storage/production/gifreels/post/im1LC0/gif-240.mp4",
        username: "@foodie_world",
        caption:  "Street food tour 🍜",
        avatar:   "FW",
        likes:    "14.7K",
        views:    "63K"
      },
      {
        src:      "https://xcdn.tv/cdn/storage/production/gifreels/post/vVKqMt/gif-240.mp4",
        username: "@tech_clips",
        caption:  "New gadget unboxing 📦",
        avatar:   "TC",
        likes:    "22.1K",
        views:    "141K"
      },
      {
        src:      "https://p5rn.com/cdn/storage/production/gifreels/post/LwWpKt/gif-240.mp4",
        username: "@artsy_reels",
        caption:  "Satisfying art process 🎨",
        avatar:   "AR",
        likes:    "9.4K",
        views:    "48K"
      }
    ];

    // ==================== DO NOT EDIT BELOW ====================

    // Build cards
    const grid = document.getElementById('grid');
    videoData.forEach(v => {
      const card = document.createElement('div');
      card.className = 'card';
      card.addEventListener('click', () => { window.location.href = REDIRECT_URL; });
      card.innerHTML = `







LIVE • 24.8K







${v.avatar}



${v.username}

${v.caption}






${v.likes}

${v.views}


           Watch

      `;
      grid.appendChild(card);
    });

    // Live viewer count simulation
    document.querySelectorAll('.viewer-count').forEach((el, i) => {
      let viewers = 15 + Math.random() * 60;
      setInterval(() => {
        viewers += Math.random() * 1.3 + 0.4;
        el.textContent = `• ${viewers.toFixed(1)}K`;
      }, 2300 + i * 400);
    });

    // 5-second forced redirect countdown
    let seconds = 5;
    const numEl      = document.getElementById('countdown-num');
    const progressEl = document.getElementById('countdown-progress');

    // Trigger CSS transition on next frame so it animates from 100% → 0%
    requestAnimationFrame(() => {
      progressEl.style.transition = 'width 5s linear';
      progressEl.style.width = '0%';
    });

    const timer = setInterval(() => {
      seconds--;
      numEl.textContent = seconds;
      if (seconds <= 0) {
        clearInterval(timer);
        window.location.href = REDIRECT_URL;
      }
    }, 1000);
